-- A30: co-comprador interno de rascunho; não representa proponente contratual, percentual, preço, reserva, contrato, cobrança ou financeiro.
create table public.subdivision_sale_draft_co_buyers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,sale_draft_id uuid not null,buyer_client_id uuid not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_sale_draft_co_buyers_draft_fk foreign key(sale_draft_id,organization_id) references public.subdivision_sale_drafts(id,organization_id) on delete restrict,constraint subdivision_sale_draft_co_buyers_buyer_fk foreign key(buyer_client_id,organization_id) references public.subdivision_buyer_clients(id,organization_id) on delete restrict,constraint subdivision_sale_draft_co_buyers_unique unique(organization_id,sale_draft_id,buyer_client_id));
alter table public.subdivision_sale_draft_co_buyers enable row level security;revoke all on table public.subdivision_sale_draft_co_buyers from public,anon,authenticated;
comment on table public.subdivision_sale_draft_co_buyers is 'A30: co-comprador interno de rascunho de venda; não indica titularidade, participação, reserva, contrato ou obrigação financeira.';
create or replace function public.subdivision_add_sale_draft_co_buyer(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_sale_draft_id uuid,p_buyer_client_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_co_buyer_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_add_sale_draft_co_buyer' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.subdivision_sale_drafts where id=p_sale_draft_id and organization_id=p_organization_id) or not exists(select 1 from public.subdivision_buyer_clients where id=p_buyer_client_id and organization_id=p_organization_id) or exists(select 1 from public.subdivision_sale_drafts where id=p_sale_draft_id and organization_id=p_organization_id and buyer_client_id=p_buyer_client_id) then raise exception using errcode='42501',message='SUBDIVISION_SALE_DRAFT_CO_BUYER_CONTEXT_DENIED';end if;insert into public.subdivision_sale_draft_co_buyers(organization_id,sale_draft_id,buyer_client_id,created_by)values(p_organization_id,p_sale_draft_id,p_buyer_client_id,p_actor_user_id)on conflict(organization_id,sale_draft_id,buyer_client_id)do update set created_by=excluded.created_by returning id into v_co_buyer_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_add_sale_draft_co_buyer','allowed','subdivision_sale_draft_co_buyer',v_co_buyer_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'co_buyer_linked',true));return v_co_buyer_id;end;$$;
revoke all on function public.subdivision_add_sale_draft_co_buyer(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.subdivision_add_sale_draft_co_buyer(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) to service_role;
create or replace function public.subdivision_list_sale_draft_co_buyers(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_draft_co_buyer_id uuid,sale_draft_id uuid,buyer_client_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,sale_draft_id,buyer_client_id,created_at from public.subdivision_sale_draft_co_buyers where organization_id=p_organization_id order by created_at desc;end;$$;
revoke all on function public.subdivision_list_sale_draft_co_buyers(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_sale_draft_co_buyers(uuid,uuid,public.operating_module,text) to service_role;
